<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { profileApi } from '../api/profile'
import { tradingApi } from '../api/trading'
const q=ref('');const items=ref<any[]>([]);const selected=ref<any>(null);const orders=ref<any[]>([]);const loading=ref(true);const error=ref('')
async function load(){loading.value=true;try{items.value=(await profileApi.customers(q.value)).data.data.items}catch(e:any){error.value=e.response?.data?.detail||e.message}finally{loading.value=false}}
async function openCustomer(id:string){try{selected.value=(await profileApi.customer(id)).data.data;orders.value=(await tradingApi.customerOrders(id)).data.data}catch(e:any){error.value=e.response?.data?.detail||e.message}}
onMounted(load)
</script>
<template><section><div class="section-heading"><div><span class="eyebrow">CUSTOMER OPERATIONS</span><h2>客户管理</h2><p>查询客户资料、账户资产、持仓和订单。</p></div><span class="pill">客户服务后台</span></div><div class="search-box"><input v-model="q" placeholder="按用户名或姓名搜索" @keyup.enter="load" /><button class="button" @click="load">搜索</button></div><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">正在读取客户…</div><div v-else class="customer-list"><article v-for="customer in items" :key="customer.id" class="result customer-row" @click="openCustomer(customer.id)"><div><div class="result-meta"><span>{{customer.username}}</span><span>{{customer.status}}</span></div><h3>{{customer.display_name}}</h3><p>投资目标：{{customer.profile?.investment_goal||'未填写'}} · 持仓：{{customer.holding_count}} 笔</p></div><strong>查看 →</strong></article><div v-if="!items.length" class="empty">暂无客户。</div></div><div v-if="selected" class="profile-panel customer-detail"><div class="section-heading compact"><div><span class="eyebrow">CUSTOMER DETAIL</span><h3>{{selected.user?.display_name}}</h3><p>{{selected.user?.username}}</p></div><button class="text-button" @click="selected=null">关闭</button></div><div class="metric-grid"><div class="metric-card"><span>总资产</span><strong>¥{{selected.latest_asset?.total_asset??0}}</strong></div><div class="metric-card"><span>可投资资产</span><strong>¥{{selected.latest_asset?.investable_asset??0}}</strong></div><div class="metric-card"><span>持仓数量</span><strong>{{selected.holdings?.length??0}}</strong></div></div><h3>持仓</h3><article v-for="holding in selected.holdings||[]" :key="holding.id" class="result"><p>产品：{{holding.product_id}} · 市值：¥{{holding.market_value}} · 盈亏：¥{{holding.profit_loss}}</p></article><h3>订单</h3><article v-for="order in orders" :key="order.id" class="result"><div class="result-meta"><span>{{order.product_name||order.product_id}}</span><span>{{order.status}}</span></div><p>订单号：{{order.order_no}} · 金额：¥{{order.amount}}</p></article><div v-if="!orders.length" class="empty">暂无订单。</div></div></section></template>
